namespace iSlideAddIn;
public static class ColorManager
{
    static readonly Dictionary<string, string[]> S = new() { ["Material Blue"] = new[]{"1976D2","2196F3","64B5F6","BBDEFB","FFFFFF"},["Material Green"]=new[]{"388E3C","4CAF50","81C784","C8E6C9","FFFFFF"},["Material Orange"]=new[]{"F57C00","FF9800","FFB74D","FFE0B2","FFFFFF"},["Corporate Blue"]=new[]{"1A237E","283593","3949AB","5C6BC0","9FA8DA"},["Corporate Gray"]=new[]{"212121","424242","616161","9E9E9E","E0E0E0"},["Warm Red"]=new[]{"B71C1C","D32F2F","E53935","EF9A9A","FFEBEE"}};
    public static void ExtractColors() { var a = AddInModule.PowerPointApp; if (a?.ActivePresentation == null) return; try { int idx = a.ActiveWindow.Selection.SlideRange.SlideIndex; dynamic slide = a.ActivePresentation.Slides[idx]; var c = new HashSet<string>(); foreach (dynamic s in slide.Shapes) { try { int rgb = s.Fill.ForeColor.RGB; if (rgb != 0) c.Add($"{rgb&0xFF:X2}{(rgb>>8)&0xFF:X2}{(rgb>>16)&0xFF:X2}"); } catch { } } M(c.Count > 0 ? $"Extracted {c.Count} colors:\n"+string.Join("\n",c.Take(10)) : "No colors found."); } catch { } }
    public static void ApplyScheme(string nm) { var a = AddInModule.PowerPointApp; if (a?.ActivePresentation == null) return; if (!S.TryGetValue(nm, out var cl)) return; try { int idx = a.ActiveWindow.Selection.SlideRange.SlideIndex; dynamic slide = a.ActivePresentation.Slides[idx]; int n = 0; foreach (dynamic s in slide.Shapes) { try { string h = cl[n%cl.Length]; s.Fill.ForeColor.RGB = (Convert.ToInt32(h.Substring(4,2),16)<<16)|(Convert.ToInt32(h.Substring(2,2),16)<<8)|Convert.ToInt32(h.Substring(0,2),16); n++; } catch { } } M($"Applied '{nm}' to {n} shapes."); } catch { } }
    static void M(string m) => System.Windows.Forms.MessageBox.Show(m, "iSlide", System.Windows.Forms.MessageBoxButtons.OK, System.Windows.Forms.MessageBoxIcon.Information);
}
